export function repository(){const rows=[];const match=(row,q)=>Object.entries(q).every(([key,value])=>String(row[key])===String(value));return {rows,find(q){return {sort(){return this;},async lean(){return rows.filter(r=>match(r,q));}};},async findOne(q){return rows.find(r=>match(r,q));},async findOneAndUpdate(q,update){let row=rows.find(r=>match(r,q));if(!row){row={...q,...update.$setOnInsert};rows.push(row);}return row;},async deleteOne(q){const index=rows.findIndex(r=>match(r,q));if(index<0)return{deletedCount:0};rows.splice(index,1);return{deletedCount:1};}};}
